# -*- coding: utf-8 -*-
from lib import *

DECIDES = 'Meta, or the platform concerned, makes the final decision on every appeal and claim. Nobody can promise an outcome, and this page does not.'

mk('white-label-account-recovery', 'White label account recovery', 'start',
 'White Label Account Recovery: Guide for Agencies',
 'What white label account recovery is, who does what, what your client sees, and when it makes sense for an agency. Plain steps, no promises.',
 'White label account recovery, explained for agencies.',
 'Your client lost an Instagram or Facebook account. You sell the fix under your own brand, and Unbanz does the platform work behind the scenes.',
 'White label account recovery means an agency sells account recovery to its own clients under its own brand, while a specialist does the platform work behind the scenes. The client only deals with the agency. Meta, or the platform concerned, makes the final decision, so no outcome can be promised.',
 [('The client sees only you', 'Unbanz works for the agency, not for the agency’s client. Your client never needs to hear our name.'),
  ('You own the relationship', 'You talk to the client, set the terms and present the result. We handle the account problem with the platform.'),
  ('The platform decides', 'Every appeal goes through the official process. Meta or the platform concerned decides, and no result is promised.')],
 [('definition', 'What the term means',
   DEFN('White label account recovery', 'A service one company produces and another company sells as its own. Here: Unbanz prepares and files the appeal or username claim, and the agency presents it to its client under the agency’s name.') +
   P('The word “recovery” covers a few different problems: a disabled or suspended Instagram or Facebook account, a hacked account, a restricted ad account or business portfolio, and a brand handle the client wants claimed. Each has its own official route, and the guides linked below explain them one by one.')),
  ('who-does-what', 'Who does what',
   TABLE(['Step', 'Agency', 'Unbanz', 'Platform'],
         [['Talks to the client', 'Yes, always', 'No', 'Sends its own notices and codes to the account owner'],
          ['Collects username, notice screenshot and date', 'Yes', 'Tells you what is missing', 'No'],
          ['Prepares and files the appeal or username claim', 'No', 'Yes, through the official process', 'Receives it'],
          ['Updates the client', 'Yes, in your own words', 'Updates you, not the client', 'No'],
          ['Decides the outcome', 'No', 'No', 'Yes']]) +
   P('Nothing in this split depends on the client knowing Unbanz exists. To see exactly what a client notices, read [[what-your-client-sees-white-label-recovery|what your client sees]].')),
  ('when', 'When it makes sense for an agency',
   UL(['Your clients regularly run social accounts or ads for you, so a lockout hits your own work.',
       'You get asked for help with disabled accounts and do not want to learn appeal routes for each platform.',
       'You want one clear answer for clients instead of sending them to a stranger on a forum.',
       'You would rather keep the client relationship than refer the client away.']) +
   P('If you only see one lockout a year, a referral may be enough. The page on [[white-label-vs-referral-vs-in-house-recovery|white label, referral and in-house]] compares the three side by side.')),
  ('services', 'What you can hand over',
   UL(['Disabled, suspended or restricted Instagram accounts: [[white-label-instagram-account-recovery|white label Instagram recovery]].',
       'Disabled or locked Facebook profiles and Pages: [[white-label-facebook-account-recovery|white label Facebook recovery]].',
       'Hacked accounts where the email, number or password was changed: [[white-label-hacked-account-recovery|white label hacked account help]].',
       'Restricted or disabled ad accounts: [[white-label-facebook-ad-account-recovery|white label ad account recovery]].',
       'Brand handles a client wants: [[white-label-username-claim|white label username claims]].',
       'Snapchat accounts: [[white-label-snapchat-account-recovery|white label Snapchat recovery]].']) +
   P('Our refund policy covers username claims: 100% refund if a username claim fails. Other terms are agreed with you before work starts.')),
  ('limits', 'What it cannot do',
   P(DECIDES) + UL(['It cannot restore an account that the platform has removed for good.', 'It does not use shortcuts, inside contacts or tricks. Unbanz is independent and not affiliated with Meta.', 'It does not take accounts that were really used to scam or abuse people.', 'It never needs a client’s password or login codes.'])),
  ('start', 'How to start',
   P('Message us on WhatsApp or email with the client’s username, an unedited screenshot of the notice and its date. You do not have to name the client. We tell you honestly if we can help, then agree terms with you before any work begins. The full routine is on [[how-white-label-account-recovery-works|how white label account recovery works]], and a checklist for the details is on [[agency-intake-form-checklist-account-recovery|the agency intake checklist]].'))],
 [('What is white label account recovery?', 'It is account recovery that an agency sells to its clients under its own brand. Unbanz does the platform work behind the scenes, the client deals only with the agency, and the platform makes the final decision.'),
  ('Does the client know Unbanz is involved?', 'No. Unbanz works for the agency, behind the scenes, under the agency’s brand. The client deals only with the agency. Platform emails and checks such as codes still reach the account owner from the platform itself.'),
  ('Can Unbanz promise the account will come back?', 'No. Meta, or the platform concerned, makes the final decision, and nobody can promise an outcome. Unbanz tells the agency honestly whether it can help before any work starts.'),
  ('Is this the same as a referral?', 'No. In a referral the client is passed to another company and deals with it. In white label the client stays with the agency and never deals with Unbanz.'),
  ('How does an agency get started?', 'Send a message on WhatsApp at +1 934 201 2490 or email team@unbanz.com with the username, a screenshot of the notice and its date. Terms are agreed with the agency before work starts.')],
 ['how-white-label-account-recovery-works', 'what-your-client-sees-white-label-recovery', 'white-label-vs-referral-vs-in-house-recovery', 'white-label-agency-glossary', 'become-a-white-label-recovery-partner'],
 'The pillar guide: definition, who does what, when it fits and what it cannot do.')

mk('how-white-label-account-recovery-works', 'How white label recovery works', 'start',
 'How White Label Account Recovery Works',
 'The white label recovery routine for agencies in plain steps: intake, go-ahead, filing, updates and wrap-up. Who does what at each stage.',
 'How white label account recovery works, step by step.',
 'From the first message about a disabled account to the final update to your client. Seven steps, and where each person fits.',
 'White label account recovery runs in seven steps: the client tells the agency, the agency gathers details, Unbanz confirms it can help, terms are agreed, Unbanz files through the official process, the agency updates the client, and the platform decides. The client only ever deals with the agency.',
 [('One contact point', 'The agency talks to Unbanz. Unbanz does not talk to the agency’s client.'),
  ('Official routes only', 'Appeals and claims go through the platform’s own process, with no tricks and no inside contacts.'),
  ('No promised outcome', 'The platform decides. You get honest updates, not predictions.')],
 [('steps', 'The seven steps',
   OL(['<strong>The client reports a problem to you.</strong> They tell you the account is disabled, hacked, restricted or that they want a handle.',
       '<strong>You collect the details.</strong> Username or profile link, an unedited screenshot of the notice, the date, the email and number on the account, and the client’s go-ahead. Use the [[agency-intake-form-checklist-account-recovery|intake checklist]].',
       '<strong>You message Unbanz</strong> on WhatsApp or by email. Naming the client is not needed.',
       '<strong>Unbanz tells you honestly whether it can help.</strong> If the situation has no legitimate route, you hear that straight away.',
       '<strong>Terms are agreed between you and Unbanz</strong> before any work starts. What you charge your own client is your decision.',
       '<strong>Unbanz prepares and files</strong> the appeal or username claim through the platform’s official process, then keeps you updated.',
       '<strong>You pass the update on</strong> to your client in your own words, using the [[client-status-update-templates-account-recovery|status update templates]]. The platform makes the final decision.'])),
  ('roles', 'Who does what at each stage',
   TABLE(['Stage', 'Client', 'Agency', 'Unbanz'],
         [['Report', 'Tells the agency', 'Listens, asks for the notice', 'Not involved yet'],
          ['Intake', 'Sends screenshot and go-ahead', 'Collects and checks details', 'Tells you what is missing'],
          ['Filing', 'Completes any check the platform sends to the account owner', 'Coordinates', 'Prepares and files'],
          ['Updates', 'Receives them from the agency', 'Writes them', 'Informs the agency'],
          ['Decision', 'Waits', 'Reports it', 'Reports it to you']])),
  ('client-checks', 'What the client may still have to do',
   P('Some steps belong to the account owner and cannot be done by anyone else. A code sent to the account email, a selfie video check or an ID request goes to the owner from the platform. Tell your client to expect it and to complete it themselves. Nobody should hand over a password or a login code to make it quicker.')),
  ('unbanz-side', 'What happens on the Unbanz side',
   P('Unbanz picks the right official route for the type of problem, prepares the appeal or claim from the details you sent, files it and watches for the response. For a disabled account that means the in-app review or appeal form. For a hacked account it means the hacked-account tools. For a restricted ad account it means the Account Quality tools. For a handle it means the trademark or impersonation reports where they apply, and a recovery route when the handle was the client’s before.') +
   P('If the platform asks for something new, you hear about it, and you decide what to tell the client.')),
  ('timing', 'About timing',
   P('The platform sets the pace, not Unbanz and not the agency. Some decisions arrive quickly and some take long, and a few never come. Do not give your client a date. Say what step the appeal is at, and say that the platform decides.')),
  ('end', 'Wrapping up',
   P('When the platform decides, you tell the client. If the account is back, remind them to turn on two-factor authentication with an authenticator app and to add a second admin where the platform allows it. See [[prevent-client-account-lockouts-agency-checklist|the lockout prevention checklist]]. If the answer is no, [[when-to-turn-down-recovery-job|what to say when it is a no]] and the status templates help you word it.'))],
 [('How many steps are there in white label recovery?', 'Seven in the usual routine: report, intake, message to Unbanz, honest answer on whether it can help, terms agreed, filing through the official process, and an update from the agency to the client.'),
  ('Does Unbanz talk to my client?', 'No. Unbanz works with the agency only. The platform may still send codes or checks to the account owner, and the owner completes those.'),
  ('What does the agency have to send first?', 'The username or profile link, an unedited screenshot of the notice with its date, the email and number on the account, and the client’s go-ahead. A password is never needed.'),
  ('How long does a decision take?', 'The platform sets the pace and no honest provider can give a date. Tell your client which step the appeal is at rather than when it will end.'),
  ('What if the answer is no?', 'The platform’s decision is final for that request. Tell the client plainly, explain what options remain, such as a new account built on safer foundations, and keep the relationship.')],
 ['white-label-account-recovery', 'agency-intake-form-checklist-account-recovery', 'client-status-update-templates-account-recovery', 'what-your-client-sees-white-label-recovery', 'account-recovery-sop-template-for-agencies'],
 'The seven-step routine, with a table of who does what.')

mk('what-your-client-sees-white-label-recovery', 'What your client sees', 'start',
 'What Your Client Sees in White Label Recovery',
 'In white label account recovery, your client sees nothing from Unbanz. What they do see, what the platform sends them, and how to prepare them.',
 'What your client sees: nothing from Unbanz.',
 'Unbanz works for you behind the scenes. This page lists exactly what reaches your client and what does not.',
 'In white label account recovery your client sees nothing from Unbanz. No message, invoice or name from us reaches them. They deal with your agency only. The platform, such as Meta, may still send its own emails, codes or checks to the account owner, so prepare your client for those.',
 [('Nothing from Unbanz', 'No messages, no invoices, no logos. Unbanz works for the agency only.'),
  ('Platform messages still arrive', 'Meta or the platform concerned writes to the account owner. That is outside anyone’s control.'),
  ('You set the story', 'You choose how to describe the service on your side, as long as you stay honest about outcomes.')],
 [('table', 'What reaches the client, and what does not',
   TABLE(['Item', 'Does the client see it?'],
         [['A message from Unbanz', 'No. Unbanz writes only to the agency.'],
          ['An Unbanz invoice or receipt', 'No. Terms and payment are between you and Unbanz. You invoice your client yourself.'],
          ['The Unbanz name or logo', 'No. Nothing is branded for the client.'],
          ['Emails and codes from Instagram, Facebook or Snapchat', 'Yes. They go to the email or number on the account.'],
          ['An ID or selfie video request from the platform', 'Yes. Only the owner can complete it.'],
          ['Your updates', 'Yes. You write them in your own words.']])),
  ('prepare', 'How to prepare your client for platform messages',
   P('A client who gets a surprise email from Meta may panic or click the wrong link. Tell them in advance which messages are coming, that they should open them only from the official app or site, and that they should never forward a code to anyone, including you and including us.') +
   TMPL('A short note you can send', 'We have started the process for your account. You may get emails or codes from the platform on the account email or phone. They are real and expected. Please do not share any code with anyone. Tell me when one arrives and I will tell you what to do next.')),
  ('own-words', 'Describing the service in your own words',
   P('You can call it your account recovery service, your platform support or whatever matches your own packaging. Stay honest about the two things that never change: a specialist does the platform work behind the scenes, and the platform decides. If a client asks you directly whether someone else is involved, answer truthfully. Using subcontractors is normal business.')),
  ('data', 'What data the client shares, and with whom',
   P('The client gives the agency the username, the notice screenshot and their go-ahead. The agency passes only what the appeal needs to Unbanz. Passwords and login codes are never part of that. More on handling client details is in [[agency-client-confidentiality-account-recovery|client confidentiality and NDAs]].')),
  ('exceptions', 'The only times the client might hear about Unbanz',
   P('If you decide to tell them. Otherwise never. Unbanz does not contact your client, does not look for them and does not mention agency clients anywhere else.'))],
 [('Does my client see anything from Unbanz?', 'No. Unbanz writes only to the agency, and nothing from Unbanz is sent to the client. The client deals with the agency alone.'),
  ('Will my client get emails from Meta?', 'Possibly. Meta or the platform concerned can send emails, codes or identity checks to the account owner during an appeal. Tell your client to expect them and to complete them personally.'),
  ('Who invoices the client?', 'The agency does. Unbanz agrees terms with the agency only, and what the agency charges its own client is its own decision.'),
  ('Should I tell my client a specialist is involved?', 'That is your decision, but do not deny it if asked directly. Stay honest about the outcome, which the platform decides.'),
  ('Does Unbanz contact my client directly?', 'No. Unbanz works with the agency only and does not contact the agency’s clients.')],
 ['white-label-account-recovery', 'how-white-label-account-recovery-works', 'agency-client-confidentiality-account-recovery', 'how-to-tell-client-account-disabled-template', 'white-label-agency-faq'],
 'Exactly what your client does and does not see.')

mk('white-label-vs-referral-vs-in-house-recovery', 'White label vs referral vs in-house', 'compare',
 'White Label vs Referral vs In-House Recovery',
 'Compare three ways an agency can handle client account lockouts: white label, referral and in-house. Who keeps the client, who does the work, what changes.',
 'White label vs referral vs in-house account recovery.',
 'Three ways to deal with a client’s disabled account. Here is how they differ and which one suits which agency.',
 'An agency can handle a client’s disabled account in three ways. In-house means your own team does the appeals. A referral sends the client to another company. White label keeps the client with you while a specialist works behind the scenes. White label keeps the relationship without building the know-how.',
 [('In-house', 'Your people do everything. Most control, most training, and it only pays off if lockouts are frequent.'),
  ('Referral', 'You pass the client on. Least work for you, but the client now has a relationship with someone else.'),
  ('White label', 'You keep the client and a specialist does the platform work. A middle path.')],
 [('table', 'The three options compared',
   TABLE(['', 'In-house', 'Referral', 'White label'],
         [['Who talks to the client', 'You', 'The other company after hand-off', 'You'],
          ['Who does the platform work', 'Your team', 'The other company', 'Unbanz, behind the scenes'],
          ['Who owns the relationship afterwards', 'You', 'Shared or lost', 'You'],
          ['Know-how you need to build', 'A lot, and it changes often', 'None', 'None'],
          ['Control over the story', 'Full', 'Little', 'Full'],
          ['Risk of the client going elsewhere', 'Low', 'Higher', 'Low'],
          ['Fits best when', 'Lockouts are frequent and you have a trained person', 'You see lockouts rarely', 'You see them sometimes and want to stay the contact']])),
  ('in-house', 'In-house: what it really asks of you',
   P('Doing it yourself means learning the appeal route for each platform and problem, keeping up as menus and rules change, and absorbing the time when a request is rejected and needs a second approach. If you have a person who enjoys that work and your volume is steady, it can be the right call. The detail is in [[white-label-vs-in-house-account-recovery|white label vs in-house]].')),
  ('referral', 'Referral: simple, with a catch',
   P('A referral costs you nothing to set up, and it feels honest. The catch is that your client now knows another company, and some will keep using it. If your agency sells retainers, that is a real cost. See [[white-label-vs-freelancer-vs-referral-recovery|white label vs freelancer vs referral]] for the freelancer angle.')),
  ('wl', 'White label: what you give up',
   P('You give up a little margin to the partner and you rely on them to be honest about what is possible. In return you keep the client, the relationship and the voice. It does not remove the platform’s authority: Meta or the platform concerned still decides.')),
  ('choose', 'Choosing between them',
   UL(['Lockouts every month and a trained person in the team: consider in-house.',
       'Lockouts a few times a year and you want to keep clients: white label.',
       'Almost never: a referral, or a clear note in your terms.']))],
 [('What is the difference between white label and a referral?', 'In a referral the client is handed to another company and deals with it. In white label the client stays with the agency and never deals with the specialist.'),
  ('Is in-house recovery cheaper than white label?', 'It depends on volume. In-house needs a trained person and time to keep up with platform changes. For occasional lockouts, white label can cost less than building that skill.'),
  ('Can I mix the options?', 'Yes. Some agencies handle simple lockouts themselves and send the rest to a white label partner. Others refer clients only for platforms they do not cover.'),
  ('Does white label change who decides the outcome?', 'No. Meta or the platform concerned decides in every option, and no provider can promise an outcome.'),
  ('Which option protects client relationships best?', 'In-house and white label both keep the client with you. A referral puts another company in front of your client.')],
 ['white-label-vs-in-house-account-recovery', 'white-label-vs-freelancer-vs-referral-recovery', 'white-label-account-recovery', 'how-to-choose-a-white-label-recovery-partner'],
 'Three-way comparison table with a clear choice rule.')

mk('white-label-vs-in-house-account-recovery', 'White label vs in-house', 'compare',
 'White Label vs In-House Account Recovery',
 'Should your agency learn to do account recovery itself or use a white label partner? What in-house really requires and when it stops making sense.',
 'White label vs in-house account recovery for agencies.',
 'Doing recovery yourself sounds simple until the third lockout. Here is what in-house actually asks of an agency.',
 'In-house account recovery means your own staff handle every appeal. It gives control but needs training, time and upkeep, because platform menus and rules change. White label gives you one trained specialist behind your brand. In-house suits steady volume and a dedicated person. White label suits occasional lockouts.',
 [('Time', 'Appeals take focus. Every hour a strategist spends on one is an hour not billed elsewhere.'),
  ('Upkeep', 'Menus, forms and rules change. Someone has to keep checking them.'),
  ('Control', 'In-house gives you full control. White label gives you control of the client, not the platform work.')],
 [('what', 'What in-house requires',
   UL(['One named person who owns appeals and knows the routes for each platform and problem type.',
       'A routine for collecting details from clients, so appeals are complete the first time.',
       'Time to follow up, and to repeat the work if a request is rejected.',
       'A way to stay current when the platform changes its forms or wording.',
       'A calm voice for clients who are frightened about losing their audience.']) +
   P('If you already have this, you may not need a partner. If you do not, writing the routine is the first step. Use the [[account-recovery-sop-template-for-agencies|SOP template]] either way.')),
  ('table', 'Side by side',
   TABLE(['Question', 'In-house', 'White label'],
         [['Who learns the routes', 'Your team', 'Unbanz'],
          ['Who talks to the client', 'You', 'You'],
          ['Who files', 'You', 'Unbanz, behind the scenes'],
          ['Training needed', 'Yes', 'No'],
          ['Time inside the agency', 'High per request', 'Low: intake and updates'],
          ['Who decides', 'The platform', 'The platform']])),
  ('hidden', 'Costs that people forget',
   UL(['The second attempt. A rejected request often needs a different approach, not a copy of the first.',
       'The client call. Clients want to talk, and a lockout is an emotional topic for a creator or founder.',
       'The documentation. If your person leaves, the knowledge leaves with them.',
       'The context switch. Your best strategist is probably not your best appeal writer.'])),
  ('hybrid', 'The hybrid that works for some agencies',
   P('Handle simple, well-understood problems in-house, such as walking a client through instagram.com/hacked. Send disabled accounts, restricted ad accounts and handle claims to a partner. Write down which is which in your SOP so everyone on the team makes the same call.')),
  ('switch', 'When to switch from in-house to white label',
   UL(['Appeals pile up on one person.', 'Your clients start asking and nobody wants to own it.', 'You notice you are guessing at the right route.', 'You would rather spend the hour on client strategy.']))],
 [('Should my agency build account recovery in-house?', 'Only if lockouts are frequent and one person can own the routes and keep up with changes. For occasional lockouts a white label partner is usually less work.'),
  ('What does in-house account recovery cost an agency?', 'The cost is mostly time: training, keeping up with platform changes and repeating work after rejections. It also ties up your most senior people.'),
  ('Can I use white label for hard accounts only?', 'Yes. Some agencies handle simple lockouts themselves and send disabled accounts, ad accounts and handle claims to a partner.'),
  ('Do I lose control with white label?', 'You keep control of the client, the terms and the message. The platform work is done by the partner, and the platform decides the result.'),
  ('How do I decide?', 'Count how many lockouts you saw in the last twelve months, then ask who on your team would own them. If the answer is nobody, white label is the safer choice.')],
 ['white-label-vs-referral-vs-in-house-recovery', 'account-recovery-sop-template-for-agencies', 'how-white-label-account-recovery-works', 'white-label-account-recovery'],
 'What in-house recovery requires and when white label is the better fit.')

mk('white-label-vs-freelancer-vs-referral-recovery', 'White label vs freelancer vs referral', 'compare',
 'White Label vs Freelancer vs Referral Recovery',
 'Compare a white label partner, a freelance recovery helper and a plain referral for your agency. Accountability, brand control and what to ask each.',
 'White label vs freelancer vs referral.',
 'You have three outside options for a client’s disabled account. They look similar and behave very differently.',
 'A white label partner works behind your brand as a company with a stable contact. A freelancer is one person you hire per job, with less continuity. A referral hands the client away. Choose by how much you need accountability, brand control and a stable point of contact.',
 [('White label partner', 'A company with a routine and a stable contact, working under your brand.'),
  ('Freelancer', 'One person, hired per request. Quality depends on that person being available.'),
  ('Referral', 'The client leaves your hands and meets another company.')],
 [('table', 'Compared',
   TABLE(['', 'White label partner', 'Freelancer', 'Referral'],
         [['Client deals with', 'You', 'You', 'The other company'],
          ['Continuity', 'A company with a stable contact', 'One person, availability varies', 'The other company'],
          ['Brand control', 'Full', 'Full', 'None'],
          ['Written terms', 'Agreed before work starts', 'Varies by person', 'Usually none'],
          ['Best when', 'You want repeat capacity', 'You need a one-off and know the person', 'You rarely meet this problem']])),
  ('freelancer', 'Working with a freelancer',
   P('A good freelancer is flexible and personal. The risk is dependence on one person: if they are unavailable, your client waits, and you carry the explanation. Ask how they keep notes, how they handle a rejected request and what they do when they are away.') +
   P('Avoid anyone who asks for a client’s password, offers to “buy back” an account or talks about insiders. See [[agency-account-recovery-red-flags|red flags for agencies]].')),
  ('partner', 'Working with a partner company',
   P('A partner such as Unbanz is built for agencies that pass this work on repeatedly. You get one place to send details, honest answers on whether a job is possible, and terms agreed in advance. You can read how it runs in [[how-white-label-account-recovery-works|how white label recovery works]].')),
  ('referral', 'Referring the client',
   P('A referral keeps your own workload low and can still be the best answer if you rarely see this problem. Decide first whether you are comfortable with the client getting to know someone else. Some agencies send referrals only to clients who already left or for platforms they do not cover.')),
  ('questions', 'Questions to ask any of the three',
   UL(['What can you not do, and how will you tell me?', 'Will you ever need my client’s password or login code?', 'Which official route will you use for this problem?', 'What happens if the first request is rejected?', 'Will you ever contact my client directly?']) +
   P('The longer version is in [[how-to-choose-a-white-label-recovery-partner|how to choose a white label recovery partner]].'))],
 [('Is a freelancer cheaper than a white label partner?', 'Sometimes per job, but cost is not the only factor. A freelancer’s availability varies, and notes and terms are often informal. Compare continuity as well as price.'),
  ('Why not just refer the client?', 'A referral is fine if you rarely meet the problem, but your client then meets another company and may stay with it. White label keeps the client with you.'),
  ('Can a freelancer work white label?', 'Yes, in the sense that they work behind your brand. The difference is continuity: one person versus a company with a routine and a stable contact.'),
  ('What should I never accept from a provider?', 'A request for the client’s password or login codes, talk of insiders at Meta, buying or selling accounts, and any promise of a sure result.'),
  ('Does the platform treat the three options differently?', 'No. Meta or the platform concerned decides every appeal the same way, whoever files it.')],
 ['white-label-vs-referral-vs-in-house-recovery', 'how-to-choose-a-white-label-recovery-partner', 'agency-account-recovery-red-flags', 'white-label-account-recovery'],
 'Partner, freelancer or referral: what changes and what to ask.')
